/*
 * Parse transform
 *
 * Post-processing for rendered HTML pages. Runs after the html-minify
 * transform (see .eleventy.js registration order). All DOM work is done
 * with posthtml 0.16 (a plain-AST parser: nodes are {tag, attrs, content},
 * text nodes are strings, the root is an array) instead of JSDOM, and
 * image generation is awaited so a build never finishes before its images
 * exist.
 *
 * Behaviors:
 *  - Wrap post/intro images in click-to-full-size links with responsive
 *    <picture> sources (generated by @11ty/eleventy-img into the
 *    persistent .cache/images directory).
 *  - Add heading permalinks + id anchors to h2/h3.
 *  - Wrap allowfullscreen iframes in a .video-player div.
 */
const fs = require('fs');

const posthtml = require('posthtml');
const {parser} = require('posthtml-parser');
const slugify = require('slugify');

const Image = require('@11ty/eleventy-img');
const minify = require('../utils/minify.js');

const IMAGE_OPTIONS = {
  widths: [300, 600, 928, 1280, 1856, 'auto'],
  formats: ['webp', 'jpeg', 'svg', 'avif', 'auto'],
  urlPath: '/assets/images/',
  outputDir: './.cache/images/',
  svgAllowUpscale: true,
  sharpOptions: {png: {compressionLevel: 9}}
};

// One generation per source image per process: the same image referenced
// by several posts (or by a post and its RSS copy) is only generated once,
// and in dev-serve mode the promise (and eleventy-img's disk cache) is
// reused across rebuilds. Entries are invalidated when the source file's
// mtime changes, so an in-place image edit during a long-lived --serve
// picks up the new bytes.
const generations = new Map();

function generateImage(file) {
  let mtime = 0;
  try {
    mtime = fs.statSync(file).mtimeMs;
  } catch {
    // Remote images can't be stat-ed; eleventy-img manages its own cache.
  }
  const cached = generations.get(file);
  if (cached && cached.mtime === mtime) return cached.promise;
  const promise = Image(file, IMAGE_OPTIONS).catch(err => {
    generations.delete(file);
    throw new Error(`Image generation failed for "${file}": ${err.message}`);
  });
  generations.set(file, {mtime, promise});
  return promise;
}

// Build the <picture> markup for an already-generated image.
//
// statsSync reports every requested format, but the generator drops
// formats it can't emit for this source — e.g. jpeg for images with an
// alpha channel (transparency can't be stored in jpeg). Filter the
// metadata to the formats that actually landed on disk, or
// generateHTML would emit <source>/<img> entries for missing files.
function pictureHtml(file, result, {alt, loading}) {
  let metadata;
  try {
    metadata = Image.statsSync(file, IMAGE_OPTIONS);
  } catch {
    // Remote images can't be stat-ed synchronously; fall back to a
    // conservative size so <img> dimensions don't shift on load.
    metadata = Image.statsByDimensionsSync(file, 1856, 1856, IMAGE_OPTIONS);
  }

  const generated = Object.keys(result);
  const filtered = {};
  for (const format of Object.keys(metadata)) {
    if (generated.includes(format)) filtered[format] = metadata[format];
  }
  if (metadata.eleventyImage !== undefined) {
    Object.defineProperty(filtered, 'eleventyImage', {
      value: metadata.eleventyImage,
      enumerable: false
    });
  }

  return Image.generateHTML(filtered, {
    class: '',
    alt,
    sizes: '(min-width: 30em) 50vw, 100vw',
    loading,
    decoding: 'async'
  });
}

/* ------------------------- posthtml helpers ------------------------- */

// posthtml 0.16: text nodes are strings, element nodes are {tag, attrs,
// content}, and the root is an array. The parser does not link parents, so
// the transform threads them down explicitly where needed.

function textContent(node) {
  let text = '';
  for (const child of node.content || []) {
    text += typeof child === 'string' ? child : textContent(child);
  }
  return text;
}

function hasClass(node, name) {
  const cls = (node.attrs && node.attrs.class) || '';
  return cls.split(/\s+/).includes(name);
}

function replaceInParent(parent, node, replacement) {
  const arr = Array.isArray(parent) ? parent : parent.content;
  if (!Array.isArray(arr)) return;
  const i = arr.indexOf(node);
  if (i === -1) return;
  arr[i] = replacement;
}

// Parse an HTML fragment into a list of posthtml nodes (for injected markup).
function parseFragment(html) {
  return parser(html, {});
}

const HEADING_ANCHOR_HTML = minify(`
        <span class="visually-hidden"> permalink</span>
        <svg fill="currentColor" aria-hidden="true" focusable="false" width="1em" height="1em" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24">
          <path d="M9.199 13.599a5.99 5.99 0 0 0 3.949 2.345 5.987 5.987 0 0 0 5.105-1.702l2.995-2.994a5.992 5.992 0 0 0 1.695-4.285 5.976 5.976 0 0 0-1.831-4.211 5.99 5.99 0 0 0-6.431-1.242 6.003 6.003 0 0 0-1.905 1.24l-1.731 1.721a.999.999 0 1 0 1.41 1.418l1.709-1.699a3.985 3.985 0 0 1 2.761-1.123 3.975 3.975 0 0 1 2.799 1.122 3.997 3.997 0 0 1 .111 5.644l-3.005 3.006a3.982 3.982 0 0 1-3.395 1.126 3.987 3.987 0 0 1-2.632-1.563A1 1 0 0 0 9.201 13.6zm5.602-3.198a5.99 5.99 0 0 0-3.949-2.345 5.987 5.987 0 0 0-5.105 1.702l-2.995 2.994a5.992 5.992 0 0 0-1.695 4.285 5.976 5.976 0 0 0 1.831 4.211 5.99 5.99 0 0 0 6.431 1.242 6.003 6.003 0 0 0 1.905-1.24l1.723-1.723a.999.999 0 1 0-1.414-1.414L9.836 19.81a3.985 3.985 0 0 1-2.761 1.123 3.975 3.975 0 0 1-2.799-1.122 3.997 3.997 0 0 1-.111-5.644l3.005-3.006a3.982 3.982 0 0 1 3.395-1.126 3.987 3.987 0 0 1 2.632 1.563 1 1 0 0 0 1.602-1.198z"/>
        </svg>`);

/* ----------------------------- transform ----------------------------- */

module.exports = async function(value, outputPath) {
  if (!outputPath.endsWith('.html')) return value;

  const transform = async root => {
    // Emulates the original selectors in document order:
    //   main article img, .intro img, main article h2|h3, main article iframe
    const NO_CTX = {inMain: false, inArticle: false, inIntro: false};

    let firstImage = true;
    const imageJobs = [];

    const processNode = (n, ctx, parent) => {
      if (n.tag === 'img' && (ctx.inArticle || ctx.inIntro)) {
        const src = n.attrs && n.attrs.src;
        if (src && !src.startsWith('data:') && !(n.attrs && n.attrs.class)) {
          const alt = (n.attrs && n.attrs.alt) || '';
          const title = (n.attrs && n.attrs.title) || null;
          // Local site images live under src/assets; site-root-relative
          // srcs need the ./src prefix so sharp can read them.
          const file = src.charAt(0) === '/' ? './src' + src : src;
          const loading = firstImage ? 'eager' : 'lazy';
          firstImage = false;

          // Generation is kicked off now and awaited after the walk, so
          // the markup only references files that actually exist.
          imageJobs.push({
            parent,
            node: n,
            src,
            file,
            alt,
            title,
            loading,
            job: generateImage(file)
          });
          return;
        }
      } else if ((n.tag === 'h2' || n.tag === 'h3') && ctx.inArticle) {
        const id = `heading-${slugify(textContent(n).toLowerCase())}`;
        if (!n.attrs) n.attrs = {};
        n.attrs.id = id;
        n.content.push({
          tag: 'a',
          attrs: {href: `#${id}`, class: 'heading-permalink'},
          content: parseFragment(HEADING_ANCHOR_HTML)
        });
      } else if (n.tag === 'iframe' && ctx.inArticle) {
        if (n.attrs && n.attrs.allowfullscreen !== undefined) {
          replaceInParent(parent, n, {
            tag: 'div',
            attrs: {class: 'video-player'},
            content: [n]
          });
          return;
        }
      }

      const children = Array.isArray(n) ? n : n.content;
      if (!children) return;
      const next = {
        inMain: ctx.inMain || n.tag === 'main',
        inArticle: ctx.inArticle || (ctx.inMain && n.tag === 'article'),
        inIntro: ctx.inIntro || !!(n.tag && hasClass(n, 'intro'))
      };
      for (const child of children) processNode(child, next, n);
    };

    for (const child of root) processNode(child, NO_CTX, root);

    // Await generation, then replace each queued <img> with its
    // <picture> markup. Awaiting here (inside the plugin) guarantees the
    // build never writes a page before its images exist, and a bad image
    // path fails the build loudly.
    for (const {parent, node, src, file, alt, title, loading, job} of imageJobs) {
      const result = await job;

      const anchor = {
        tag: 'a',
        attrs: {
          href: src,
          class: 'img',
          title: 'Click to view full-size'
        },
        content: parseFragment(pictureHtml(file, result, {alt, loading}))
      };

      if (title) {
        replaceInParent(parent, node, {
          tag: 'figure',
          attrs: {},
          content: [anchor, {tag: 'figcaption', attrs: {}, content: parseFragment(title)}]
        });
      } else {
        replaceInParent(parent, node, anchor);
      }
    }
  };

  const {html: output} = await posthtml([transform]).process(value);
  return output;
};
